const DEFAULT_PRECISION: usize = 6;

pub fn format_float(value: f32) -> String {
    if value.is_nan() {
        return if value.is_sign_negative() {
            String::from("-nan")
        } else {
            String::from("nan")
        };
    }

    if value.is_infinite() {
        return if value.is_sign_negative() {
            String::from("-inf")
        } else {
            String::from("inf")
        };
    }

    if value == 0.0 {
        return if value.is_sign_negative() {
            String::from("-0")
        } else {
            String::from("0")
        };
    }

    let value = value as f64;
    let scientific = format!("{:.*e}", DEFAULT_PRECISION - 1, value);
    let rounded_exponent = parse_exponent(&scientific);

    if (-4..DEFAULT_PRECISION as i32).contains(&rounded_exponent) {
        let decimals = (DEFAULT_PRECISION as i32 - 1 - rounded_exponent).max(0) as usize;
        trim_fraction(format!("{:.*}", decimals, value))
    } else {
        format_scientific(scientific)
    }
}

fn parse_exponent(scientific: &str) -> i32 {
    let (_, exponent) = scientific.split_once('e').expect("scientific format");
    exponent.parse::<i32>().expect("valid exponent")
}

fn format_scientific(scientific: String) -> String {
    let (mantissa, exponent) = scientific.split_once('e').expect("scientific format");
    let exponent = exponent.parse::<i32>().expect("valid exponent");
    let sign = if exponent < 0 { '-' } else { '+' };
    let magnitude = exponent.abs();
    let mantissa = trim_fraction(mantissa.to_owned());
    format!("{mantissa}e{sign}{magnitude:02}")
}

fn trim_fraction(mut text: String) -> String {
    if text.contains('.') {
        while text.ends_with('0') {
            text.pop();
        }
        if text.ends_with('.') {
            text.pop();
        }
    }
    text
}

