#[derive(Clone, Copy, Debug)]
pub struct RGB {
    pub r: f32,
    pub g: f32,
    pub b: f32,
}

impl RGB {
    pub const fn new(r: f32, g: f32, b: f32) -> Self {
        Self { r, g, b }
    }
}

#[derive(Clone, Copy, Debug)]
struct HSL {
    h: f32,
    s: f32,
    l: f32,
}

impl HSL {
    const fn new(h: f32, s: f32, l: f32) -> Self {
        Self { h, s, l }
    }
}

pub struct ColorConverter;

impl ColorConverter {
    pub fn adjust_saturation(rgb: RGB, factor: f32) -> RGB {
        let mut hsl = Self::rgb_to_hsl(rgb);
        hsl.s = clamp(hsl.s * factor, 0.0, 1.0);
        Self::hsl_to_rgb(hsl)
    }

    fn rgb_to_hsl(rgb: RGB) -> HSL {
        let r = rgb.r;
        let g = rgb.g;
        let b = rgb.b;

        let max = cpp_max(cpp_max(r, g), b);
        let min = cpp_min(cpp_min(r, g), b);
        let l = (max + min) / 2.0;

        if max == min {
            return HSL::new(0.0, 0.0, l);
        }

        let delta = max - min;
        let s = if l > 0.5 {
            delta / ((2.0 - max) - min)
        } else {
            delta / (max + min)
        };

        let mut h = if r == max {
            let base = (g - b) / delta;
            let offset = if b > g { 6.0 } else { 0.0 };
            offset + base
        } else if g == max {
            2.0 + ((b - r) / delta)
        } else {
            4.0 + ((r - g) / delta)
        };

        h = (h / 6.0) * 360.0;
        HSL::new(h, s, l)
    }

    fn hsl_to_rgb(hsl: HSL) -> RGB {
        const ONE_SIXTH: f32 = 1.0 / 6.0;
        const ONE_THIRD: f32 = 1.0 / 3.0;
        const TWO_THIRDS: f32 = 2.0 / 3.0;

        let h = hsl.h / 360.0;
        let s = hsl.s;
        let l = hsl.l;

        if s == 0.0 {
            return RGB::new(l, l, l);
        }

        let q = if l < 0.5 {
            (1.0 + s) * l
        } else {
            (l + s) - (l * s)
        };
        let p = (2.0 * l) - q;

        let r = hue_to_rgb(p, q, h + ONE_THIRD, ONE_SIXTH, TWO_THIRDS);
        let g = hue_to_rgb(p, q, h, ONE_SIXTH, TWO_THIRDS);
        let b = hue_to_rgb(p, q, h - ONE_THIRD, ONE_SIXTH, TWO_THIRDS);

        RGB::new(r, g, b)
    }
}

fn hue_to_rgb(p: f32, q: f32, mut t: f32, one_sixth: f32, two_thirds: f32) -> f32 {
    if t < 0.0 {
        t = 1.0 + t;
    }
    if t > 1.0 {
        t -= 1.0;
    }
    if t < one_sixth {
        return p + ((6.0 * (q - p)) * t);
    }
    if t < 0.5 {
        return q;
    }
    if t < two_thirds {
        return p + (6.0 * ((q - p) * (two_thirds - t)));
    }
    p
}

fn cpp_max(lhs: f32, rhs: f32) -> f32 {
    if lhs < rhs { rhs } else { lhs }
}

fn cpp_min(lhs: f32, rhs: f32) -> f32 {
    if rhs < lhs { rhs } else { lhs }
}

fn clamp(value: f32, min: f32, max: f32) -> f32 {
    if min > value {
        min
    } else if value > max {
        max
    } else {
        value
    }
}

